 static MacroService instance; boolean running=false; Handler h=new Handler(Looper.getMainLooper()); String pkg; LocalDate start,pending,target,laterCandidate; boolean preview; Set<String> seen=new HashSet<>(),booked=new HashSet<>(); String state=""; long due,deadline; int idle,scrolls,success,skips; String lastSig="",lastDump=""; Set<String> closedCards=new HashSet<>(),inspectedCards=new HashSet<>(); String pendingCard=""; int returnScroll=0; WindowManager wm; LinearLayout overlay; TextView info;
 static final Pattern FULL=Pattern.compile("(?<!\\d)(20\\d{2})(?:[.\\-/년\\s]+)(\\d{1,2})(?:[.\\-/월\\s]+)(\\d{1,2})(?!\\d)|(?<!\\d)(20\\d{2})(\\d{2})(\\d{2})(?!\\d)");
 static final Pattern SHORT=Pattern.compile("(?<!\\d)(\\d{1,2})(?:[.\\-/월]\\s*|\\s+)(\\d{1,2})(?!\\d)(?=\\s*(?:[.()일월화수목금토]|픽업|$))");
 static final Pattern PICKUP=Pattern.compile("(?<!\\d)(\\d{1,2})[.\\-/월]\\s*(\\d{1,2})(?:\\s*일)?\\s*(?:\\([월화수목금토일]\\))?\\s*픽업");
