 static class Item{AccessibilityNodeInfo node;String text,raw;Rect r=new Rect();Item(AccessibilityNodeInfo n,String s){node=n;raw=s;text=norm(s);n.getBoundsInScreen(r);}}
 LocalDate parse(String s){Matcher m=FULL.matcher(s);try{if(m.find())return LocalDate.of(Integer.parseInt(m.group(1)!=null?m.group(1):m.group(4)),Integer.parseInt(m.group(2)!=null?m.group(2):m.group(5)),Integer.parseInt(m.group(3)!=null?m.group(3):m.group(6)));m=SHORT.matcher(s);if(m.find()){LocalDate now=LocalDate.now();LocalDate d=LocalDate.of(now.getYear(),Integer.parseInt(m.group(1)),Integer.parseInt(m.group(2)));if(d.isBefore(now.minusMonths(6)))d=d.plusYears(1);if(d.isAfter(now.plusMonths(6)))d=d.minusYears(1);return d;}}catch(Exception ignored){}return null;}
 @Override public void onServiceConnected(){instance=this;}
