 void begin(String p,LocalDate d,boolean dry,MealSelection selected){if(running)return;selection=selected;TAB=selected.tab;pkg=p;start=d;preview=dry;seen.clear();closedCards.clear();inspectedCards.clear();pendingCard="";returnScroll=0;lastDump="";booked=new HashSet<>(prefs().getStringSet(selection.key,Collections.emptySet()));seen.addAll(booked);target=PickupParser.nextEligible(start,seen);laterCandidate=null;pending=null;idle=scrolls=success=skips=0;lastSig="";state="OPEN";running=true;deadline=SystemClock.uptimeMillis()+20*60*1000;due=SystemClock.uptimeMillis()+1600;show();trace("\n=== v1.2.0 RUN "+LocalDateTime.now()+" package="+p+" start="+d+" selection="+selection.display+" tab="+TAB+" preview="+dry+" ===");log(selection.display+" 시작 "+d+(dry?" (탐색만)":""));log("목표 날짜 "+target);h.post(tick);}
 void stop(String reason){if(!running)return;running=false;h.removeCallbacks(tick);if(pending!=null&&("RESULT".equals(state)||"CONFIRM".equals(state)))reason+=" · "+pending+" 결과 미확인, 주문 내역 확인 필요";log(reason+" / 완료 "+success+"건");if(overlay!=null){try{wm.removeView(overlay);}catch(Exception ignored){}overlay=null;info=null;}}
 void show(){wm=(WindowManager)getSystemService(WINDOW_SERVICE);overlay=new LinearLayout(this);overlay.setOrientation(0);overlay.setGravity(Gravity.CENTER_VERTICAL);overlay.setPadding(12,4,8,4);overlay.setBackgroundColor(0xee182b21);info=new TextView(this);info.setTextColor(Color.WHITE);info.setMaxLines(2);info.setTextSize(12);overlay.addView(info,new LinearLayout.LayoutParams(0,-2,1));Button b=new Button(this);b.setText("중지");b.setOnClickListener(v->stop("사용자 중지"));overlay.addView(b);WindowManager.LayoutParams lp=new WindowManager.LayoutParams(getResources().getDisplayMetrics().widthPixels*4/5,-2,WindowManager.LayoutParams.TYPE_ACCESSIBILITY_OVERLAY,WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE|WindowManager.LayoutParams.FLAG_NOT_TOUCH_MODAL,PixelFormat.TRANSLUCENT);lp.gravity=Gravity.TOP|Gravity.CENTER_HORIZONTAL;try{wm.addView(overlay,lp);}catch(Exception e){overlay=null;info=null;}}
 void walk(AccessibilityNodeInfo n,List<Item> out,int depth){if(n==null||depth>40||out.size()>1500)return;if(n.isVisibleToUser()&&!n.isPassword()&&!"android.widget.EditText".contentEquals(n.getClassName()==null?"":n.getClassName())){if(n.getText()!=null)out.add(new Item(n,n.getText().toString()));if(n.getContentDescription()!=null&&!Objects.equals(n.getText(),n.getContentDescription()))out.add(new Item(n,n.getContentDescription().toString()));}for(int i=0;i<n.getChildCount();i++)walk(n.getChild(i),out,depth+1);}
 Item exact(List<Item>a,String t){for(Item i:a)if(i.text.equals(t)&&!i.r.isEmpty())return i;return null;}
 boolean contains(List<Item>a,String t){for(Item i:a)if(i.text.contains(t))return true;return false;}
 boolean tap(Item i){if(i==null||!i.node.isEnabled()||i.r.isEmpty())return false;AccessibilityNodeInfo n=i.node;for(int k=0;n!=null&&k<5;k++,n=n.getParent())if(n.isClickable()&&n.isEnabled()&&n.performAction(AccessibilityNodeInfo.ACTION_CLICK))return true;Rect r=i.r;Path path=new Path();path.moveTo(r.exactCenterX(),r.exactCenterY());return dispatchGesture(new GestureDescription.Builder().addStroke(new GestureDescription.StrokeDescription(path,0,80)).build(),null,null);}
 void next(String s,long ms){trace("STATE "+state+" -> "+s+" wait="+ms+"ms");state=s;idle=0;due=SystemClock.uptimeMillis()+ms;}
