 void waitMore(){if(idle==0||idle==7||idle==14)trace("WAIT state="+state+" attempt="+(idle+1)+" pending="+pending);if(++idle>14){stop("화면 인식 시간 초과: "+state);return;}due=SystemClock.uptimeMillis()+500;}
 boolean swipe(boolean down){trace("SWIPE "+(down?"DOWN":"UP")+" state="+state+" count="+scrolls);int w=getResources().getDisplayMetrics().widthPixels,hh=getResources().getDisplayMetrics().heightPixels;Path p=new Path();p.moveTo(w*.32f,hh*(down?.72f:.32f));p.lineTo(w*.32f,hh*(down?.32f:.72f));return dispatchGesture(new GestureDescription.Builder().addStroke(new GestureDescription.StrokeDescription(p,0,440)).build(),null,null);}
 String sig(List<Item>a){StringBuilder b=new StringBuilder();for(Item i:a)if(i.text.contains("픽업")||i.text.contains("헬시팩")||i.text.contains("샐러드")||i.text.contains("투고서비스")||i.text.contains("도시락세트"))b.append(i.text).append('@').append(i.r.top/30).append(';');return b.toString();}
 LocalDate detailDate(List<Item>a){for(Item i:a){LocalDate d=PickupParser.detail(i.raw,LocalDate.now());if(d!=null)return d;}for(Item i:a)if(i.text.contains("픽업날짜")||i.text.equals("픽업일")||i.text.equals("픽업일자")){ArrayList<Item> row=new ArrayList<>();row.add(i);for(Item j:a)if(j!=i&&Math.abs(j.r.centerY()-i.r.centerY())<Math.max(35,i.r.height()))row.add(j);for(Item j:row){LocalDate d=parseFull(j.raw);if(d!=null)return d;}row.sort(Comparator.comparingInt(j->j.r.left));StringBuilder b=new StringBuilder();for(Item j:row)b.append(j.raw).append(" ");LocalDate full=parseFull(b.toString());if(full!=null)return full;for(Item j:row){LocalDate d=parseDetailShort(j.raw);if(d!=null)return d;}return parseDetailShort(b.toString());}return null;}
 LocalDate parseDetailShort(String s){Matcher m=SHORT.matcher(s);if(!m.find())return null;try{int month=Integer.parseInt(m.group(1)),day=Integer.parseInt(m.group(2));if(pending!=null&&pending.getMonthValue()==month&&pending.getDayOfMonth()==day)return pending;return parse(s);}catch(Exception e){return null;}}
 LocalDate parseFull(String s){return FULL.matcher(s).find()?parse(s):null;}
 boolean oneQuantity(List<Item>a){for(Item i:a){Integer q=PickupParser.quantity(i.raw);if(q!=null){trace("QUANTITY parsed="+q);return q==1;}}Item label=exact(a,"수량");if(label==null){for(Item i:a)if(i.text.matches("수량[:：]?1"))return true;return false;}for(Item i:a){if(Math.abs(i.r.centerY()-label.r.centerY())>Math.max(35,label.r.height()))continue;if(i.text.equals("1")||i.text.matches("수량[:：]?1")||i.text.matches("[−–-]?1[+]"))return true;}return label.text.matches("수량[:：]?1");}
 Item reserveButton(List<Item>a){Item i=exact(a,"예약하기");if(i!=null)return i;for(Item j:a)if(j.text.matches("예약하기(?:버튼)?")&&j.node.isEnabled()&&!j.r.isEmpty())return j;return null;}
 boolean directTap(Item i){if(i==null||!i.node.isEnabled()||i.r.isEmpty())return false;Rect r=i.r;Path p=new Path();p.moveTo(r.exactCenterX(),r.exactCenterY());return dispatchGesture(new GestureDescription.Builder().addStroke(new GestureDescription.StrokeDescription(p,0,100)).build(),new GestureResultCallback(){@Override public void onCompleted(GestureDescription g){trace("RESERVE gesture completed");}@Override public void onCancelled(GestureDescription g){trace("RESERVE gesture cancelled");stop("예약 터치 취소");}},h);}
 String diagnostics(List<Item>a){StringBuilder b=new StringBuilder();for(Item i:a){if(i.text.contains("픽업")||i.text.contains("예약")||i.text.contains("수량")||i.text.matches("[0-9. /년월일()-]+")){if(b.length()>700)break;b.append("[").append(i.raw).append("] ");}}return b.toString();}
 String describe(Item i){return "'"+i.raw.replace('\n',' ').replace('\r',' ')+"' bounds="+i.r.toShortString()+" class="+i.node.getClassName()+" id="+i.node.getViewIdResourceName()+" enabled="+i.node.isEnabled()+" clickable="+i.node.isClickable();}
 File traceFile(){return new File(getFilesDir(),"mealcare-diagnostic.txt");}
 void trace(String line){try{File f=traceFile();if(f.length()>1500000){File prev=new File(getFilesDir(),"mealcare-diagnostic-prev.txt");if(prev.exists())prev.delete();f.renameTo(prev);}try(FileOutputStream out=new FileOutputStream(f,true)){out.write((LocalTime.now().withNano(0)+" ["+state+"] "+line+"\n").getBytes(StandardCharsets.UTF_8));}}catch(Exception ignored){}}
 void snapshot(List<Item>a,AccessibilityNodeInfo root){StringBuilder b=new StringBuilder();b.append("WINDOW ").append(root.getClassName()).append(" nodes=").append(a.size()).append('\n');int count=0;for(Item i:a){if(++count>250){b.append("... truncated\n");break;}b.append(describe(i)).append('\n');}String dump=b.toString();String key=state+"|"+dump;if(!key.equals(lastDump)){lastDump=key;trace(dump);}}
 void advance(LocalDate d){LocalDate old=target;target=PickupParser.nextEligible(d.plusDays(1),seen);laterCandidate=null;trace("NEXT_TARGET "+old+" -> "+target);log("다음 목표 "+target);}
 void record(LocalDate d,boolean ok){seen.add(d.toString());if(ok){booked.add(d.toString());prefs().edit().putStringSet(selection.key,new HashSet<>(booked)).commit();success++;log(d+" 예약 완료");}else{skips++;log(d+" "+(preview?"탐색 확인":"예약 제외"));}advance(d);}
