 final Runnable tick=new Runnable(){public void run(){if(!running)return;try{if(SystemClock.uptimeMillis()>deadline){stop("실행 제한 도달");return;}if(SystemClock.uptimeMillis()>=due)step();}catch(Exception e){trace(android.util.Log.getStackTraceString(e));stop("오류: "+e.getClass().getSimpleName());}if(running)h.postDelayed(this,350);}};
 void step(){AccessibilityNodeInfo root=getRootInActiveWindow();if(root==null||!pkg.equals(String.valueOf(root.getPackageName()))){if(idle==0)trace("WAIT target window: "+(root==null?"null":root.getPackageName()));waitMore();return;}List<Item>a=new ArrayList<>();walk(root,a,0);snapshot(a,root);
 if("RESULT".equals(state)){if(contains(a,"예약이완료되었습니다")||contains(a,"예약이완료")){record(pending,true);pending=null;Item ok=exact(a,"확인");if(!move(ok,"RETURN"))stop("예약 완료, 확인 버튼 인식 실패");return;}if(contains(a,"이미예약")||contains(a,"이미신청")){record(pending,false);pending=null;if(!move(exact(a,"확인"),"RETURN"))backToList();return;}waitMore();return;}
 if("DETAIL".equals(state)){if(!contains(a,"상세메뉴")){if(idle==0)trace("DETAIL waiting for title");waitMore();return;}boolean correctProduct=false;for(Item i:a)if(selection.product(i.raw)){correctProduct=true;break;}if(!correctProduct){stop("선택한 식사/메뉴와 다른 상품 상세 화면: "+selection.display);return;}LocalDate d=detailDate(a);if(d==null){if(idle==0)log("상세 날짜 인식 실패: "+diagnostics(a));waitMore();return;}trace("DETAIL expected="+pending+" actual="+d+" start="+start);if(pending==null||!pending.equals(d)){stop("목록/상세 날짜 불일치: "+pending+" / "+d);return;}pending=d;if(!d.equals(target)||seen.contains(d.toString())||PickupParser.weekend(d)){stop("목표 날짜와 상세 날짜 불일치: "+target+" / "+d);return;}
 Item reserve=reserveButton(a);if(contains(a,"예약불가")||contains(a,"예약마감")||contains(a,"이미예약")||contains(a,"CLOSED")||(reserve!=null&&!reserve.node.isEnabled())){record(d,false);backToList();return;}
 if(preview){record(d,false);backToList();return;}if(reserve==null){if(idle==0)log("예약 버튼 인식 실패: "+diagnostics(a));waitMore();return;}if(!oneQuantity(a)){stop("수량 1 확인 실패: "+diagnostics(a));return;}trace("RESERVE "+describe(reserve)+" quantity verified");if(!directTap(reserve)){stop("예약 버튼 터치 실패: "+diagnostics(a));return;}next("RESULT",1600);log(d+" 예약 버튼 터치");return;}
 if(contains(a,"상세메뉴")||contains(a,"예약이완료되었습니다")){stop("예상하지 못한 상세/완료 화면");return;}
 Item tab=exact(a,TAB);if(tab==null)for(Item i:a)if(i.text.startsWith(TAB+"탭")&&!i.r.isEmpty()){tab=i;break;}if("OPEN".equals(state)||"RETURN".equals(state)){if(tab!=null){boolean resetHome=false;for(Item i:a)if(selection.otherTabProduct(i.raw)){resetHome=true;break;}if(move(tab,resetHome?"SCAN":"TOP")){lastSig="";scrolls=0;laterCandidate=null;return;}}Item smart=exact(a,"스마트오더");if(move(smart,"OPEN"))return;waitMore();return;}
 boolean wrongTab=false;for(Item i:a)if(selection.otherTabProduct(i.raw)&&i.text.contains("픽업")){wrongTab=true;break;}if(wrongTab){trace("WAIT tab switch to "+TAB);if(idle>=7&&tab!=null&&tab.node.isClickable()){if(move(tab,"TOP")){lastSig="";scrolls=0;return;}}waitMore();return;}if(tab==null){boolean anySelected=false;for(Item i:a)if(selection.product(i.raw)){anySelected=true;break;}if(!anySelected){waitMore();return;}}if("TOP".equals(state)){String now=sig(a);if(now.equals(lastSig)||scrolls>=35){lastSig="";scrolls=0;next("SCAN",400);return;}lastSig=now;scrolls++;swipe(false);due=SystemClock.uptimeMillis()+850;return;}
 if("SCAN".equals(state)){ArrayList<Item> products=new ArrayList<>();for(Item i:a)if(selection.product(i.raw)){PickupParser.Card card=PickupParser.card(i.raw,LocalDate.now(),selection);trace("MATCH "+describe(i)+" -> "+(card==null?"NO_MATCH":card.date+" closed="+card.closed));if(card!=null)products.add(i);}
 products.sort(Comparator.comparing(i->PickupParser.card(i.raw,LocalDate.now(),selection).date));
 boolean targetVisible=false,closedTarget=false,openTarget=false;
 for(Item i:products){PickupParser.Card card=PickupParser.card(i.raw,LocalDate.now(),selection);LocalDate d=card.date;
 if(PickupParser.weekend(d)||d.isBefore(target)||seen.contains(d.toString())){trace("SKIP "+d+" target="+target+" weekend/earlier/handled");continue;}
 if(d.isAfter(target)){if(!card.closed&&i.node.isEnabled()&&(laterCandidate==null||d.isBefore(laterCandidate)))laterCandidate=d;continue;}
 targetVisible=true;if(card.closed){closedTarget=true;trace("TARGET CLOSED "+d);continue;}openTarget=true;
 if(!i.node.isEnabled()||!i.node.isClickable()){trace("WAIT target not clickable "+d);waitMore();return;}
 if(i.r.height()<Math.max(40,getResources().getDisplayMetrics().heightPixels/22)){trace("TARGET clipped "+d+"; keep searching");continue;}
 pending=d;trace("SELECT "+d+" exact target");if(move(i,"DETAIL"))return;stop("상품 클릭 실패: "+d);return;}
 if(closedTarget&&!openTarget){record(target,false);lastSig="";idle=0;due=SystemClock.uptimeMillis()+500;return;}
 String now=sig(a);if(now.isEmpty()){if(idle==0)trace("No list signature; visible nodes="+a.size());if(++idle>=5){stop(selection.display+" 상품 목록 없음 또는 인식 불가");return;}due=SystemClock.uptimeMillis()+700;return;}
 if(now.equals(lastSig)){if(++idle>=3){if(targetVisible&&openTarget){stop("목표 상품이 화면에 있지만 선택할 수 없음: "+target);return;}if(laterCandidate!=null){LocalDate candidate=laterCandidate;trace("FULL_SCAN no target "+target+"; next available weekday "+candidate);target=PickupParser.nextEligible(candidate,seen);laterCandidate=null;lastSig="";scrolls=0;log("상품 없는 날짜 건너뜀 · 다음 목표 "+target);next("TOP",500);return;}stop(selection.display+" 예약 가능 평일 탐색 종료 · 다음 목표 "+target);return;}}else idle=0;
 if(++scrolls>70){stop("스크롤 제한 도달 · 미확인 목표 "+target);return;}lastSig=now;swipe(true);due=SystemClock.uptimeMillis()+1000;return;}

 waitMore();
 }
